import React, { useState, useEffect } from 'react';
import axios from 'axios';
import './googlemap.css'; // ייבוא קובץ ה-CSS

const Map = () => {
    const [map, setMap] = useState(null);
    const [microchipNumber, setMicrochipNumber] = useState('');
    const [location, setLocation] = useState(null);

    useEffect(() => {
        const script = document.createElement('script');
        script.src = `https://maps.googleapis.com/maps/api/js?key=YOUR_API_KEY&callback=initMap`;
        script.async = true;
        script.defer = true;
        script.onload = () => {
            initMap();
        };
        document.head.appendChild(script);

        return () => {
            document.head.removeChild(script);
        };
    }, []);

    const initMap = () => {
        const kafrYirka = { lat: 32.9533, lng: 35.2176 };

        const newMap = new window.google.maps.Map(document.getElementById('map'), {
            zoom: 12,
            center: kafrYirka
        });

        setMap(newMap);
    };

    const fetchLocation = async () => {
        try {
            const response = await axios.get(`http://localhost:3001/api/pets/${microchipNumber}`);
            setLocation(response.data.location);
        } catch (error) {
            console.error('Error fetching location:', error);
        }
    };

    useEffect(() => {
        if (location && map) {
            const [lat, lng] = location.split(',').map(Number);
            const newLocation = { lat, lng };
            map.setCenter(newLocation);
            new window.google.maps.Marker({
                position: newLocation,
                map: map
            });
        }
    }, [location, map]);

    return (
        <div className="container">
            <div className="header">Pet Tracker</div>
            <input
                type="text"
                placeholder="Enter Microchip Number"
                value={microchipNumber}
                onChange={(e) => setMicrochipNumber(e.target.value)}
            />
            <button className="button" onClick={fetchLocation}>Find Pet</button>
            <div id="map" style={{ height: '400px', width: '100%' }}></div>
        </div>
    );
};

export default Map;
